class Solution {
    public int singleNumber(int[] nums) {
        int result = 0;
        for (int bit = 0; bit < 32; bit++) {
            int count = 0;
            for (int num : nums) {
                if (((num >>> bit) & 1) == 1) {
                    count++;
                }
            }
            if ((count & 1) == 1) {
                result |= (1 << bit);
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int singleNumber(int[] nums) {
        Set<Integer> pending = new HashSet<>();
        for (int num : nums) {
            if (!pending.add(num)) {
                pending.remove(num);
            }
        }
        return pending.iterator().next();
    }
}

